import subprocess, os
def run_timeout(args, term="dumb", timeout=2):
    env=dict(os.environ); env["TERM"]=term
    try:
        r=subprocess.run(args, capture_output=True, timeout=timeout, env=env)
        return (r.returncode, r.stdout, r.stderr)
    except subprocess.TimeoutExpired as e:
        return ("TIMEOUT", e.stdout or b'', e.stderr or b'')

# Test -u values with TERM=dumb quickly; use timeout utility? subprocess timeout includes curses loop, so TIMEOUT means it entered curses (valid). immediate return means error/usage
