// charsets
// default charset: ASCII 33..122
static char def_charset[128];
static int def_len = 0;
static void init_def(void) {
    if (def_len) return;
    int k=0;
    for (int i=33;i<=122;i++) def_charset[k++]=(char)i;
    def_len=k;
}

// katakana string as UTF-8
static const char *kata_str = "ｦｧｨｩｪｫｬｭｮｯｰｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓﾔﾕﾖﾗﾘﾙﾚﾛﾜ";
// high chars for -x : U+00A6..U+00D8
static const char *high_str = "¦§¨©ª«¬­®¯°±²³´µ¶·¸¹º»¼½¾¿ÀÁÂÃÄÅÆÇÈÉÊËÌÍÎÏÐÑÒÓÔÕÖ×Ø";

// helper to get random UTF-8 char from a UTF-8 string (by character, not byte)
// We need to pick random character (Unicode codepoint) from string, return as newly allocated? Simpler: pre-split into array of strings.
#define MAXCHARS 128
static char *def_chars_arr[MAXCHARS];
static int def_chars_n=0;
static char *kata_arr[128];
static int kata_n=0;
static char *high_arr[128];
static int high_n=0;

// split UTF-8 string into array of char* (each malloced)
static int split_utf8(const char *s, char *out[], int max) {
    int n=0;
    const unsigned char *p=(const unsigned char*)s;
    while (*p && n<max) {
        int len=1;
        unsigned char c=*p;
        if ((c&0x80)==0) len=1;
        else if ((c&0xE0)==0xC0) len=2;
        else if ((c&0xF0)==0xE0) len=3;
        else if ((c&0xF8)==0xF0) len=4;
        else len=1;
        char *buf=malloc(len+1);
        memcpy(buf,p,len);
        buf[len]='\0';
        out[n++]=buf;
        p+=len;
    }
    return n;
}

static void init_char_arrays(void) {
    static int done=0;
    if (done) return;
    done=1;
    init_def();
    // default: each ASCII char as separate string
    for (int i=0;i<def_len;i++) {
        char *b=malloc(2);
        b[0]=def_charset[i]; b[1]='\0';
        def_chars_arr[def_chars_n++]=b;
    }
    kata_n=split_utf8(kata_str, kata_arr, 128);
    high_n=split_utf8(high_str, high_arr, 128);
}

static const char *rand_def(void) {
    return def_chars_arr[rand()%def_chars_n];
}
static const char *rand_kata(void) {
    return kata_arr[rand()%kata_n];
}
static const char *rand_high(void) {
    return high_arr[rand()%high_n];
}

int main(int argc, char *argv[]) {
    int update=4;
    int color=2; // green
    int bold=0; // 0 none,1 white-only(cmd -n),2 random,3 all
    int async=0;
    int oldstyle=0;
    int rainbow=0;
    int lambda_flag=0;
    int japanese=0;
    int xmode=0;
    int screensaver=0;
    int lock=0;
    int force_linux=0;
    int linux_mode=0;
    int change_flag=0;
    char *tty=NULL;
    char *message=NULL;

    opterr=0;
    int c;
    while ((c=getopt(argc, argv, "abBcfhlLmnorsxVkM:u:C:t:"))!=-1) {
        switch(c) {
            case 'a': async=1; break;
            case 'b': if (bold!=3) bold=2; break;
            case 'B': bold=3; break;
            case 'c': japanese=1; break;
            case 'f': force_linux=1; break;
            case 'h': print_usage(); return 0;
            case 'l': linux_mode=1; break;
            case 'L': lock=1; break;
            case 'm': lambda_flag=1; break;
            case 'n': bold=1; break;
            case 'o': oldstyle=1; break;
            case 'r': rainbow=1; break;
            case 's': screensaver=1; break;
            case 'x': xmode=1; break;
            case 'V': print_version(); return 0;
            case 'k': change_flag=1; break;
            case 'M': message=optarg; break;
            case 'u': update=atoi(optarg); break;
            case 'C': {
                if (!strcasecmp(optarg,"green")) color=2;
                else if (!strcasecmp(optarg,"red")) color=1;
                else if (!strcasecmp(optarg,"blue")) color=4;
                else if (!strcasecmp(optarg,"white")) color=7;
                else if (!strcasecmp(optarg,"yellow")) color=3;
                else if (!strcasecmp(optarg,"cyan")) color=6;
                else if (!strcasecmp(optarg,"magenta")) color=5;
                else if (!strcasecmp(optarg,"black")) color=0;
                else {
                    fprintf(stderr," Invalid color selection\n Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                    return 0;
                }
                break;
            }
            case 't': tty=optarg; break;
            case '?':
            default: print_usage(); return 0;
        }
    }

    // force linux (with NULL deref bug to segfault when TERM unset)
    if (force_linux) {
        char *t = getenv("TERM");
        if (strcmp(t, "linux")!=0) {
            putenv("TERM=linux");
        }
    }

    FILE *ttyfp=NULL;
    if (tty) {
        ttyfp=fopen(tty,"r+");
        if (!ttyfp) {
            fprintf(stderr,"cmatrix: error: '%s' couldn't be opened: %s.\n", tty, strerror(errno));
            return 1;
