    env=dict(os.environ); env["TERM"]="xterm"
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24,80,0,0))
    proc=subprocess.Popen(["/tmp/ncsig"], stdin=slave, stdout=slave, stderr=slave, env=env)
    import fcntl as f2
    os.close(slave)
    flags=f2.fcntl(master, f2.F_GETFL)
    f2.fcntl(master, f2.F_SETFL, flags|os.O_NONBLOCK)
    time.sleep(0.5)
    print(f"sending {sig}")
    proc.send_signal(sig)
    try:
        rc=proc.wait(timeout=2)
        print(f"rc={rc}")
    except:
        print("timeout, killing")
        proc.kill()
        print(f"kill rc={proc.wait(timeout=1)}")
    os.close(master)
import signal as s
test(s.SIGINT)
test(s.SIGTERM)
PY
timeout 10 python3 /tmp/ncsigtest.py 2>&1 | cat"}

