import pty, os, select, time, subprocess, fcntl, termios, struct, signal
def run(exe, args, sig):
    env=dict(os.environ); env["TERM"]="xterm"
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24,80,0,0))
    proc=subprocess.Popen([exe]+args, stdin=slave, stdout=slave, stderr=slave, env=env)
    os.close(slave)
    import fcntl as f2
    flags=f2.fcntl(master, f2.F_GETFL)
    f2.fcntl(master, f2.F_SETFL, flags|os.O_NONBLOCK)
    out=b""
    start=time.time()
    sent=False
    while time.time()-start<2.0:
